        });
      },
      build: buildBloc,
      act: (bloc) => bloc.add(const ExportRequested(null, null)),
      wait: const Duration(milliseconds: 20),
      expect: () => [
        const ExportPending(),
        const ExportPending(),
        const ExportProcessing(),
