      tester,
      RecordsLoaded(entries: [buildEntry(id: 'e1')], nextCursor: null, isLoadingMore: false),
    );

    await tester.tap(find.byIcon(Icons.download_outlined));
    await tester.pump();
    expect(find.byType(ExportSheetProbe), findsOneWidget);

    await tester.tap(find.byIcon(Icons.close_fullscreen), warnIfMissed: false);
    Navigator.of(tester.element(find.byType(ExportSheetProbe))).pop();
    await tester.pumpAndSettle();
    expect(find.byType(ExportSheetProbe), findsNothing);

    await tester.tap(find.byIcon(Icons.download_outlined));
    await tester.pump();
    expect(find.byType(ExportSheetProbe), findsOneWidget);
  });

  testWidgets(
    '5: opening/closing the export sheet leaves RecordsBloc\'s own state untouched',
    (tester) async {
      final seeded = RecordsLoaded(
        entries: [buildEntry(id: 'e1')],
        nextCursor: null,
        isLoadingMore: false,
      );
      await pumpRecordsPage(tester, seeded);

      await tester.tap(find.byIcon(Icons.download_outlined));
      await tester.pump();
      Navigator.of(tester.element(find.byType(ExportSheetProbe))).pop();
      await tester.pumpAndSettle();

      verifyNever(() => recordsBloc.add(any()));
      expect(recordsBloc.state, seeded);
    },
  );
}

